import subprocess, pty, os, time, struct, fcntl, termios
def test_key(key_bytes, name):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    proc = subprocess.Popen(["./executable","/tmp/test.json"], stdin=slave, stdout=slave, stderr=slave, close_fds=True, preexec_fn=os.setsid)
    import os as _os
    _os.close(slave)
    time.sleep(0.6)
    _os.write(master, key_bytes)
    time.sleep(0.6)
    poll = proc.poll()
    if poll is not None:
        print(f"{name!r} quit with {poll}")
    else:
        print(f"{name!r} did not quit, sending q")
        _os.write(master, b'q')
        time.sleep(0.5)
        print(f"  after q poll={proc.poll()}")
        if proc.poll() is None:
            proc.terminate()
            try: proc.wait(timeout=1)
            except: proc.kill()
    try: _os.close(master)
    except: pass
    try: proc.wait(timeout=1)
    except: pass

open("/tmp/test.json","w").write('{"a": 1}')
for k, n in [(b'Q','Q'), (b'q','q'), (b'\x1b','esc'), (b'\x03','ctrl-c'), (b'\x04','ctrl-d'), (b' ', 'space'), (b'\n','newline'), (b'\r','cr')]:
    test_key(k, n)
