def parse_args(argv):
    help_f = False
    version_f = False
    key_f = False
    fullscreen_f = False
    files = []
    invalid = False
    end_of_flags = False
    for arg in argv:
        if end_of_flags:
            files.append(arg)
            continue
        if arg == "--":
            end_of_flags = True
            continue
        if arg.startswith("--"):
            if arg == "--help":
                help_f = True
            elif arg == "--version":
                version_f = True
            elif arg == "--key" or arg == "--keybinding":
                key_f = True
            elif arg == "--fullscreen":
                fullscreen_f = True
            else:
                invalid = True
        elif arg.startswith("-") and len(arg) > 1:
            for ch in arg[1:]:
